    void despliega(String mensaje);          // LJ(CONLJ, MSGLJ)
}

/** CALE, FUNCTIONNAME="LOCSUP.": solo se usan las funciones 6, 8 y 18 con formato 13. */
public interface CalendarioBancario {
    boolean esDiaHabil(LocalDate fecha);     // THECALENDAR función 18: FECHA1 = "00000001" si es hábil
    DayOfWeek diaSemana(LocalDate fecha);    // función 6
    LocalDate sumaDias(LocalDate f, int n);  // función 8, FECHA2 = "00000001"
}

