/** $SET SHARING = SHAREDBYRUNUNIT: un bean singleton sin estado mutable entre llamadas. */
@Service
@RequiredArgsConstructor
public class ControlS151Service implements ControlS151 {
    private final SistemaDiaRepository b01;
    private final ArchivoIntermedioRepository b02;
    private final BaseMensualRepository b03;
    private final SistemaRepository b04;
    private final ProcesoRepository b05;
    private final ConexionSistemaRepository b09;
    private final CalendarioBancario calendario;
    private final MensajeriaConsola consola;
}

/** Resultado de cada entry point. El valor numérico se conserva para los llamadores que lo evalúan. */
public enum ResultadoControl {
    OK(0),
    NO_EXISTE(1),
    FUNCION_INVALIDA(2),
    YA_EXISTE(3),
    ERROR_CALENDARIO(4),             // día inhábil o falla de LOCSUP
    MODALIDAD_INVALIDA(5),
    CSI_INVALIDO(6),
    TIPO_BD_INVALIDO(7),
    // 8 no tiene significado en el catálogo del fuente
    NOMBRE_BASE_VACIO(9),            // ERRORDB también regresa 9 ante cualquier error DMSII
    FECHA_NO_EXISTE(10),
    STATUS_INVALIDO(11),
    NUMERO_BASE_INVALIDO(12),
    AAMM_INVALIDO(13),
    BLOQUEO_AGOTADO(14);             // dos DEADLOCK seguidos; usado en el código, ausente del catálogo

    private final int codigo;
    ResultadoControl(int codigo) { this.codigo = codigo; }
    public int codigo() { return codigo; }
}

/** EXPORT: la misma superficie, un método por entry point, con DTO tipado en lugar del arreglo EBCDIC. */
public interface ControlS151 {
    ResultadoControl b02ArcInt(ArchivoIntermedioDto datos);   // S151B02ARCINTER
    ResultadoControl conSisDia(SistemaDiaDto datos);          // consultas y cambios parciales a B01
    ResultadoControl conSisB01(ConsultaSistemasDto datos);
    ResultadoControl mantSisDia(SistemaDiaDto datos);         // altas, bajas y cambios de B01
    ResultadoControl b04Sistem(SistemaDto datos);
    ResultadoControl mantB04Sistem(SistemaDto datos);
    ResultadoControl conSisMen(BaseMensualDto datos);         // B03
    ResultadoControl mantSisMen(BaseMensualDto datos);
    ResultadoControl b05Procesos(ProcesoDto datos);           // bitácora de procesos y Mix ID
    ResultadoControl b09ConXSis(ConexionSistemaDto datos);
    ResultadoControl bdAccess(int funcion);                   // 01 cierra, otro valor abre
}

/** OPEN UPDATE + FREEZE(TEMPORARY): la base se valida al arrancar y el pool vive mientras haya usuarios. */
@Component
@RequiredArgsConstructor
class ControlS151Arranque implements ApplicationListener<ApplicationReadyEvent> {
    private final DataSource ds;
    private final MensajeriaConsola consola;

    @Override
    public void onApplicationEvent(ApplicationReadyEvent e) {
        try (var c = ds.getConnection()) {
            c.isValid(20);                                     // MYSELF.MAXWAIT := 20
        } catch (SQLException ex) {
            consola.despliega("S151/L001/002:I>020101<ERROR EN BD99CONTROL");
            throw new IllegalStateException("S151BD99CONTROL no disponible", ex);   // MYSELF.STATUS := -1
        }
    }
}

@Component
@RequiredArgsConstructor
class SistemaDiaFinder {

    private final SistemaDiaRepository b01;
    private final MensajeriaConsola consola;

    /** BUSCASISDIA: hasta dos intentos; el segundo DEADLOCK devuelve BLOQUEO_AGOTADO (14). */
    @Retryable(retryFor = PessimisticLockingFailureException.class, maxAttempts = 2,
               backoff = @Backoff(delay = 0))
    @Transactional(readOnly = true)
    public Optional<SistemaDia> busca(String sistema, int csi) {
        return b01.findBySistemaAndCsi(sistema, csi);          // B01SXSISDIA
    }

    @Recover
    Optional<SistemaDia> agotado(PessimisticLockingFailureException e, String sistema, int csi) {
        throw new ControlException(ResultadoControl.BLOQUEO_AGOTADO, e);
    }

    ResultadoControl resultado(Optional<SistemaDia> r, String sistema, int csi) {
        if (r.isEmpty()) {
            consola.despliega("NO EXISTE SISTEMA %04d PARA CSI %02d".formatted(Integer.parseInt(sistema), csi));
            return ResultadoControl.NO_EXISTE;
        }
        return ResultadoControl.OK;
    }
}

@Component
@RequiredArgsConstructor
class EscrituraControl {

    private final SistemaDiaRepository b01;

    /**
     * STORE_B01(ACCION). BEGINTRANSACTION con AUDITERROR tipo 1 significa que el llamador ya
     * tiene una transacción abierta: se escribe dentro de ella y no se cierra.
     * Propagation.REQUIRED reproduce exactamente eso.
     */
    @Transactional(propagation = Propagation.REQUIRED)
    public ResultadoControl guarda(SistemaDia registro, Accion accion) {
        try {
            if (accion == Accion.STORE) b01.save(registro); else b01.delete(registro);
            return ResultadoControl.OK;
        } catch (DataAccessException e) {
            // En la transacción propia el fuente ejecuta ERRORDB (RESULT := 9).
            // En la del llamador el ERRORDB está comentado: el error se pierde y RESULT queda en 0.
            log.error("L001/CONTROL, ERROR EN DMSII ESTRUCTURA S151B01SISDIA", e);
            throw new ControlException(ResultadoControl.NOMBRE_BASE_VACIO, e);   // 9: no se oculta
        }
    }

    enum Accion { STORE, DELETE }
}

@Service
@RequiredArgsConstructor
class AltaSistemaDia {

    private static final int DIAS_CALENDARIO = 10;      // B01-SIS-FECARCMOV[1..10]
    private final SistemaDiaFinder finder;
    private final EscrituraControl escritura;
    private final CalendarioBancario cal;

    /** ALTA_SISDIA (función 19). */
    @Transactional
    public ResultadoControl alta(SistemaDiaDto d) {
        if (finder.bloquea(d.sistema(), d.csi()).isPresent()) {
            return ResultadoControl.YA_EXISTE;                    // RESULT := 3
        }
        LocalDate fecha = d.fechaProceso();
        if (!cal.esDiaHabil(fecha)) {
            return ResultadoControl.ERROR_CALENDARIO;             // RESULT := 4
        }
        int numDia = cal.diaSemana(fecha).getValue();             // función 6; ver pendiente sobre la numeración
        if (numDia < 1 || numDia > 5) {
            throw new IllegalStateException("Día hábil fuera de lunes a viernes: " + fecha);  // el fuente haría STORE sin CREATE
        }
        var reg = SistemaDia.nuevo(d, fecha, numDia);              // CREATE + PUT, STAREG = 0, NUMARC = NUMDIA
        reg.fijaDiaArchivo(numDia, fecha);

        // Avanza día por día y ocupa la siguiente posición con cada día de lunes a viernes,
        // sin volver a consultar la función 18: los feriados entre semana sí ocupan posición.
        int pos = numDia;
        LocalDate f = fecha;
        while (pos < DIAS_CALENDARIO) {
            f = cal.sumaDias(f, 1);                               // función 8
            int dia = cal.diaSemana(f).getValue();
            if (dia > 1 && dia < 6) reg.fijaDiaArchivo(++pos, f); // el fuente usa > 1, no > 0
        }
        // ... segundo ciclo (líneas 1170-1201): llena las posiciones 1..NUMDIA-1 con los días siguientes
        return escritura.guarda(reg, EscrituraControl.Accion.STORE);
    }
}

@Component
@RequiredArgsConstructor
class MantSisDiaDispatcher {

    private final AltaSistemaDia alta;
    private final BajaSistemaDia baja;
    private final CambioSistemaDia cambio;
    private final ControlProperties props;          // s151.control.csi-unico: 0

    /** MANTSISDIA: el bloque externo (cuyo comentario dice CONSISDIA) normaliza el CSI y despacha. */
    public ResultadoControl mantSisDia(SistemaDiaDto d) {
        // B01 se guarda con CSI 0 sin importar el CSI que envía el llamador.
        SistemaDiaDto n = d.csi() > 0 ? d.conCsi(props.csiUnico()) : d;
        return switch (n.funcion()) {
            case 19 -> alta.alta(n);
            case 22 -> baja.baja(n);
            case 37 -> cambio.cambio(n);
            default -> ResultadoControl.FUNCION_INVALIDA;   // RESULT := 2
        };
    }
}

@Service
@RequiredArgsConstructor
class BitacoraProcesos {

    private final ProcesoRepository b05;
    private final EscrituraControl escritura;

    /** ALTA_B05 (función 19). Llave: sistema, fecha de proceso, número de proceso, fecha inicio, registro inicial. */
    @Retryable(retryFor = PessimisticLockingFailureException.class, maxAttempts = 2, backoff = @Backoff(delay = 0))
    @Transactional
    public ResultadoControl alta(ProcesoDto p) {
        var llave = new ProcesoId(p.sistema(), p.fechaProceso(), p.numProceso(),
                                  p.fechaInicio(), p.numRegInicial());
        if (b05.existsById(llave)) {
            return ResultadoControl.YA_EXISTE;   // el fuente hace FREE y regresa 0: ver riesgo
        }
        var reg = new Proceso(llave, p.programa(), p.statusPrograma(),
                p.mixId(),                       // B05-SIS-MIX: número de mix de la tarea MCP
                p.horaInicio(), p.fechaFin(), p.horaFin(), p.numRegFinal());
        return escritura.guardaProceso(reg);    // STORE_B05(0)
    }

    @Recover
    ResultadoControl agotado(PessimisticLockingFailureException e, ProcesoDto p) {
        return ResultadoControl.BLOQUEO_AGOTADO;  // el fuente no asigna 14 en ALTA_B05: regresa 0
    }
}
